from pathlib import Path
import json,sys
ROOT=Path(__file__).resolve().parents[1]
def check(ok,label):
    if not ok:
        print('FAIL - '+label);sys.exit(1)
    print('PASS - '+label)
main=(ROOT/'wordpress/sustainable-catalyst-workspace/sustainable-catalyst-workspace.php').read_text()
php=(ROOT/'wordpress/sustainable-catalyst-workspace/includes/class-sc-workspace.php').read_text()
reg=(ROOT/'wordpress/sustainable-catalyst-workspace/includes/class-sc-workspace-registry.php').read_text()
js=(ROOT/'wordpress/sustainable-catalyst-workspace/assets/js/workspace-v0.29.0.js').read_text()
lifecycle=(ROOT/'wordpress/sustainable-catalyst-workspace/assets/js/sc-workspace-project-lifecycle-v1.js').read_text()
audit=(ROOT/'wordpress/sustainable-catalyst-workspace/assets/js/sc-workspace-audit-trail-v1.js').read_text()
css=(ROOT/'wordpress/sustainable-catalyst-workspace/assets/css/workspace-v0.29.0.css').read_text()
manifest=json.loads((ROOT/'release-manifest-v0.29.0.json').read_text())
record=json.loads((ROOT/'registry/workspace-product-record-v0.29.0.json').read_text())
check('Version: 0.29.0' in main,'plugin version')
check("define('SC_WORKSPACE_VERSION', '0.29.0')" in main,'runtime version')
check(manifest['version']=='0.29.0' and manifest['previous_version']=='0.28.0','manifest release lineage')
check(manifest['release_name']=='Governance Milestones & Project Lifecycle','release name')
check(manifest['storage_schema_version']==27 and manifest['project_schema']=='sc-workspace-project/12.0','storage 27 / project 12.0')
check(manifest['schema_migration_required'] and manifest['migration']['storage_from']==26 and manifest['migration']['storage_to']==27,'v0.28 storage migration 26 to 27')
check(not manifest['migration']['project_schema_unchanged'] and manifest['migration']['project_schema_from']=='sc-workspace-project/11.0','project migration 11.0 to 12.0')
check("'/project-lifecycle-contract'" in php and 'public function project_lifecycle_contract()' in php,'Project Lifecycle REST contract')
check(manifest['project_lifecycle_schema']=='sc-workspace-project-lifecycle/1.0' and manifest['governance_milestone_schema']=='sc-workspace-governance-milestone/1.0','lifecycle schemas')
check(manifest['project_lifecycle']['states']==['draft','evidence-ready','analysis-ready','decision-ready','review-ready','publication-ready','institutional-ready'],'seven lifecycle states')
check(manifest['project_lifecycle']['human_declared'] and not manifest['project_lifecycle']['automatic_advancement'],'human-declared lifecycle / no automatic advancement')
check(not manifest['project_lifecycle']['hidden_readiness_score'] and not manifest['project_lifecycle']['readiness_is_certification'],'no lifecycle score or certification')
check(manifest['project_lifecycle']['rationale_required'] and manifest['project_lifecycle']['acknowledgement_required'],'rationale and acknowledgement required')
check(manifest['project_lifecycle']['backward_transitions_allowed'],'backward lifecycle transitions supported')
check('data-scw-workspace-view="lifecycle"' in php and 'data-scw-workspace-section="lifecycle"' in php,'Lifecycle workspace view')
check('lifecycle: lifecycleTemplate()' in js and 'function migrateV26(raw)' in js,'project lifecycle storage migration')
check('automaticAdvance:false' in lifecycle and 'score:null' in lifecycle and 'readinessIsCertification:false' in lifecycle,'transparent lifecycle helper governance')
check('project-lifecycle' in manifest['audit_trail']['event_sources'] and "'project-lifecycle'" in audit,'Audit Trail lifecycle integration')
check('data-storage-version="27"' in php,'rendered storage version')
check('/* v0.29.0 — Governance Milestones & Project Lifecycle */' in css,'Lifecycle visual layer')
check(manifest['canonical_library_path']=='/knowledge-libraries/' and '/knowledge-libraries/' in php,'canonical Knowledge Library route')
check(record['public_version']=='0.29.0' and record['previous_version']=='0.28.0','registry record lineage')
check("BACKUP_KEY = 'sc_workspace_registry_backup_v0290'" in reg and "PENDING_KEY = 'sc_workspace_registry_pending_v0290'" in reg and 'LEGACY_PENDING_KEY_V0280' in reg,'registry pending/backup lineage')
check((ROOT/'history/release-manifest-v0.28.0.json').exists() and (ROOT/'history/workspace-product-record-v0.28.0.json').exists(),'v0.28.0 history preserved')
for f in ('sc-workspace-project-lifecycle-v1.schema.json','sc-workspace-governance-milestone-v1.schema.json','sc-workspace-project-v12.schema.json'):
    json.loads((ROOT/'schemas'/f).read_text())
check(True,'Lifecycle schema JSON')
print('VALIDATION PASSED: Sustainable Catalyst Workspace v0.29.0 — Governance Milestones & Project Lifecycle')
